package main

import (
	"github.com/thealmightychuck/pokedexcli/internal/pokeapi"
)

func main() {

	apiClient := pokeapi.NewClient()

	// - cfg holds the memory address (pointer) of the config instance.
	// - That config instance holds the map generated by getCommands().
	cfg := &config{
		commands: getCommands(),
		client:   &apiClient,
		pokedex: make(map[string]pokeapi.Captured_Pokemon),
	}
	startREPL(cfg)
}
